        } catch (ex) {
            this.errorLogAndXmatterAlert("WARNING", '- Exception while checking isCallback for ObjectID: ' + objectID + '. Error: ' + ex.message);
        }
    },

    //MSSTRESURY-538:Show number of rejected tasks by users
    updateRejection: function(taskType, reopened, assignedToDisplay, existingRejection) {
        gs.info('taskType' + taskType + 'assignedToDisplay' + assignedToDisplay + 'existingRejection' + existingRejection);

        // Parse existing rejection if it is a JSON string
        let existing = existingRejection;
        if (typeof existing == 'string') {
            try {
                existing = JSON.parse(existing);
            } catch (e) {
                existing = null;
            }
        }
        gs.info('rejection=existing' + existing);
        existing = JSON.parse(existing);
        // Base structure
        let rejection = (existing && Array.isArray(existing.users)) ? {
            total: Number(existing.total) || 0,
            taskType: existing.taskType || taskType,
            users: existing.users.slice()
        } : {
            total: 0,
            taskType: taskType,
            users: []
        };
        // Sanitize user entries
        rejection.users = rejection.users
            .filter(u =>
                u &&
                typeof u.assignedToDisplay == 'string' &&
                Number.isInteger(u.count) &&
                u.count >= 0
            );

        // Deduplicate by sys_id
        if (rejection.users.length > 1) {
            const map = {};
            for (const u of rejection.users) {
                if (!map[u.assignedToDisplay]) {
                    map[u.assignedToDisplay] = {
                        ...u
                    };
                } else {
                    map[u.assignedToDisplay].count += u.count;
                }
            }
            rejection.users = Object.values(map);
        }
        // Update / insert
        if (assignedToDisplay) {
            let found = rejection.users.find(u => u.assignedToDisplay == assignedToDisplay);

            if (found) {
                found.count += 1;
            } else {
                rejection.users.push({
                    assignedToDisplay,
                    count: 1
                });
            }
        }
        gs.info('rejection=' + JSON.stringify(rejection));
        // Recalculate total
        rejection.total = rejection.users.reduce((sum, u) => sum + u.count, 0);
        // Optional override rule
        if (reopened !== null && reopened >= rejection.total) {
            rejection.total = reopened;
        }

        // Persist detailed structure
        existingRejection = JSON.stringify(rejection);
        gs.info('Rejection: ' + JSON.stringify(rejection));
        return rejection;
    },


    //MSSTREASURY-316: Get Banding Approvals
    getBandApproval: function(taskBand, userSysID) {
        try {
            var groupType;
            var grGroupType = new GlideRecord('sys_user_group_type'); // Get Group Type SysID
            grGroupType.addEncodedQuery('name=' + taskBand);
            grGroupType.query();
            if (grGroupType.next())
                groupType = grGroupType.sys_id;

            var grMember = new GlideRecord('sys_user_grmember');
            grMember.addEncodedQuery('group.typeLIKE' + groupType + '^user=' + userSysID); // check if user has band permissions
            grMember.query();
            if (grMember.next())
                return true;
            else
                return false;
        } catch (e) {
            this.errorLogAndXmatterAlert("WARNING", 'Function : getBandApproval :- Unknown exception while processing' + e.message);
        }
    },

    //MSSTRESURY-627: Disable Record History in Treasury Workspace
    handleUnstructuredCaseClosure: function(unstructuredCaseSysId) {
        try {
            // Check if all related Instruction Cases for this Unstructured Case are closed
            var instrCaseGR = new GlideRecord('x_hsb11_mss_tsd_treasury_case');
            instrCaseGR.addQuery('unstructured_case_id', unstructuredCaseSysId); // assuming 'parent_case' links to unstructured case
            instrCaseGR.addQuery('case_type', 'Instruction Case');
            instrCaseGR.addQuery('state', '!=', '2');
            instrCaseGR.query();
            if (!instrCaseGR.hasNext()) {
                // All related instruction cases are closed, so close the unstructured case
                var unstructuredCaseGR = new GlideRecord('x_hsb11_mss_tsd_treasury_case');
                if (unstructuredCaseGR.get(unstructuredCaseSysId)) {
                    unstructuredCaseGR.state = 2;
                    unstructuredCaseGR.update();
                }
            }
        } catch (e) {
            this.errorLogAndXmatterAlert("MINOR", 'Function : handleUnstructuredCaseClosure :- Unknown exception while processing' + e.message);
        }
    },

    // MSSTRESURY-685: ITM closed-complete Treasury case check
    isClosedCompleteITMTreasuryCase: function(payload) {
        try {
            if (!payload || !Array.isArray(payload.Data) || !payload.Data.length)
                return false;
            var caseId = payload.Data[0].Id;
            if (!caseId)
                return false;
            var gr = new GlideRecord('x_hsb11_mss_tsd_treasury_case');
            if (gr.get(caseId) && gr.state == 2 || gr.task_status == 'INSTRUCTION_NACK_RECEIVED') // 2 = Closed Complete
                return caseId;
            return false;
        } catch (e) {
            this.errorLogAndXmatterAlert("WARNING", 'Function : isClosedCompleteITMTreasuryCase :- Unknown exception while processing' + e.message);
            return false;
        }
    },

    //MSSTREASURY-941 To Display Request new limit button
    isCallbackThresholdCaseOpen: function(market) {

        try {
            var table = new GlideRecord('x_hsb11_mss_tsd_treasury_case');
            table.addQuery('case_type', 'Threshold Case');
            table.addQuery('state', '1');
            table.addQuery('market', market);
            table.query();
            if (table.hasNext()) {

                return false;
            }
            return true;
        } catch (error) {
            gs.error("MSS_Treasury: MSS_Treasury_Utils.isCallbackThresholdCaseOpen() " + error);
        }


    },
    /**
     * @param {'CRITICAL'|'MAJOR'|'MINOR'|'WARNING'|'INFO'} severity
     * @param {string} txt
     */
    xMatterAlert(severity, txt) {
        try {
            new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent(severity || "WARNING", txt, 'MSSiQubeSN');
        } catch (errorInfo) {
            gs.error('Treasury - Script Include - MSS_Treasury_Utils: Function : xMatterAlert :- Unknown exception while processing' + errorInfo.message);
        }
    },

    errorLogAndXmatterAlert(severity, message) {
        const logPrefix = "Treasury - Script Include - MSS_Treasury_Utils: ";
        const finalMessage = logPrefix + message;
        gs.error(finalMessage);
        this.xMatterAlert(severity, finalMessage);
    },

    type: 'MSS_Treasury_Utils'
});
